    `).run(session, termLabel) as { lastInsertRowid: number | bigint };
    const termId = Number(termResult.lastInsertRowid);

    // 3. Create a "Legacy Class" placeholder for students already in the system
    let classId: number;
    const existingClass = db.prepare("SELECT id FROM classes WHERE name='Legacy Class' AND section IS NULL").get() as any;
    if (existingClass) {
      classId = existingClass.id;
    } else {
      const classResult = db.prepare(
        "INSERT INTO classes (name, section, level) VALUES ('Legacy Class', NULL, 'junior')"
      ).run() as { lastInsertRowid: number | bigint };
      classId = Number(classResult.lastInsertRowid);
    }

    // 4. Enroll every existing student into the legacy class for the new term
    const students = db.prepare("SELECT id FROM users WHERE role='student' AND is_active=1").all() as Array<{ id: number }>;
    const enrollStmt = db.prepare("INSERT OR IGNORE INTO class_enrollments (student_id, class_id, term_id) VALUES (?, ?, ?)");
    for (const s of students) {
      enrollStmt.run(s.id, classId, termId);
    }

    console.log(`[db v5] Bootstrap complete: term="${termLabel}" (${session}), class="Legacy Class", enrolled ${students.length} existing students.`);
  })();
}

