    const ev = queries.getCalendarEvent.get(eventId) as any;
    if (!ev) return apiError(404, "Event not found");
    const body = await readJson(req);
    const VALID_EVENT_TYPES = ["holiday","exam_period","resumption","event","deadline","other"];
