        answer: 3,
        difficulty: 1,
        topic: "Organs of Government"
      }
    ]
  },
  // PHYSICS
  {
    subject: "Physics",
    code: "PHY101",
    year: 1983,
    questions: [
      {
        text: "Which of the following is NOT a vector quantity?",
        options: ["Force", "Altitude", "Weight", "Displacement", "Acceleration"],
        answer: 1, // Altitude
        difficulty: 1,
        topic: "Mechanics"
      },
      {
